contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner, address caller) public payable {
        require(newOwner != address(0), "newOwner must be nonzero");
        require(caller != address(0), "caller must be nonzero");

        // Establish that msg.sender is the current owner by driving c's public
        // state-changing entry with msg.sender as the caller. On success, msg.sender
        // becomes the owner; if it reverts, msg.sender is not owner.
        bool becameOwner = false;
        try {
            c.transferOwnership(newOwner);
            becameOwner = true;
        } catch {
            becameOwner = false;
        }

        // If msg.sender was already the owner, transferOwnership(newOwner)
        // succeeded and set owner = newOwner. If it was not the owner, it reverted.
        address ownerBefore = c.owner();
        bool callerIsCurrentOwner = (msg.sender == ownerBefore) || becameOwner;

        // Re-establish a clean state: make msg.sender the owner by transferring
        // ownership to msg.sender (only works if msg.sender is the current owner).
        bool setSelfOwner = false;
        try {
            c.transferOwnership(msg.sender);
            setSelfOwner = true;
        } catch {
            setSelfOwner = false;
        }

        // If setSelfOwner is false, msg.sender is not the current owner, so
        // calling owned() must revert. If setSelfOwner is true, msg.sender is
        // the current owner, so owned() must succeed.
        bool ownedReverted;
        try c.owned() {
            ownedReverted = false;
        } catch {
            ownedReverted = true;
        }

        address ownerAfter = c.owner();
        assert(ownedReverted == !setSelfOwner);
        assert(ownerAfter == msg.sender || !setSelfOwner);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        require(newOwner != address(0), "newOwner must be nonzero");

        // Advance c's public state so that msg.sender becomes its owner.
        c.transferOwnership(msg.sender);

        address ownerBefore = c.owner();
        require(ownerBefore == msg.sender, "failed to become owner");

        // Now call the deciding entry point owned() as the owner.
        bool ownedReverted;
        try c.owned() {
            ownedReverted = false;
        } catch {
            ownedReverted = true;
        }

        address ownerAfter = c.owner();

        // As the owner, owned() must succeed, and ownership must be unchanged.
        assert(!ownedReverted);
        assert(ownerAfter == ownerBefore);

        // Transfer ownership away and confirm a call by a non-owner reverts.
        c.transferOwnership(newOwner);
        require(c.owner() == newOwner, "ownership transfer failed");

        bool ownedRevertedNonOwner;
        try c.owned() {
            ownedRevertedNonOwner = false;
        } catch {
            ownedRevertedNonOwner = true;
        }

        assert(ownedRevertedNonOwner);
        assert(c.owner() == newOwner);
    }

    receive() external payable {}
}

