    }

    function run(address newOwner) public payable {
        require(newOwner != address(0), "newOwner must be nonzero");

        // Make msg.sender the owner so we can later observe both owner and non-owner behavior.
        c.transferOwnership(msg.sender);

        address ownerBefore = c.owner();

        // Deciding call: as current owner, owned() must succeed.
        bool ownerCallReverted;
        try c.owned() {
            ownerCallReverted = false;
        } catch {
            ownerCallReverted = true;
        }

        address ownerAfterOwnerCall = c.owner();

        // Transfer ownership to newOwner, making msg.sender a non-owner.
        c.transferOwnership(newOwner);

        address ownerBeforeNonOwnerCall = c.owner();

        // Deciding call: as non-owner, owned() must revert.
        bool nonOwnerCallReverted;
        try c.owned() {
            nonOwnerCallReverted = false;
        } catch {
            nonOwnerCallReverted = true;
        }

        address ownerAfterNonOwnerCall = c.owner();

        // General rule: owner call succeeds; non-owner call reverts; ownership unchanged by owned().
        assert(
            !ownerCallReverted &&
            ownerAfterOwnerCall == ownerBefore &&
            nonOwnerCallReverted &&
            ownerBeforeNonOwnerCall == newOwner &&
            ownerAfterNonOwnerCall == newOwner
        );
    }

    receive() external payable {}
}

