contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address a, address newOwner) public payable {
        // Precondition only on parameters: we simulate that `a` is the caller by
        // checking whether a is the current owner, but the actual call to c
        // is made by this contract. To cover both owner and non-owner paths
        // without requiring a specific c state before any setup, we drive c
        // first through its public surface.
        require(a != address(0) || newOwner != address(0));

        // Capture the owner before the deciding call. The owner is public state.
        address beforeOwner = c.owner();

        // If a is not the current owner, the contract-level call from this test
        // will not match c.owner() (which is address(this)), so transferOwnership
        // must revert. We can also explicitly test the non-owner path by requiring
        // a != beforeOwner. But to avoid a precondition on c state before the call,
        // we let a be a parameter and use it only to decide whether the call should
        // succeed based on msg.sender == beforeOwner.
        bool isCallerOwner = (a == beforeOwner);

        // The deciding call goes through transferOwnership.
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: since this test contract is the actual msg.sender,
        // transferOwnership succeeds iff this test contract is the owner.
        // The parameter `a` is used as a proxy for the caller identity; when
        // a == beforeOwner, the caller is the owner and the call must succeed;
        // otherwise it must revert.
        if (a == beforeOwner) {
            assert(!reverted && c.owner() == newOwner);
        } else {
            assert(reverted && c.owner() == beforeOwner);
        }
    }

    receive() external payable {}
}

